mapper.select:
SELECT source_hash,
       translated_text,
       status,
       failure_count,
       retry_after,
       lease_until
  FROM content_translation
 WHERE source_type = #{sourceType}
   AND source_key = #{sourceKey}
   AND source_field = #{sourceField}
   AND target_language = #{targetLanguage}

mapper.update:
UPDATE content_translation
   SET source_hash = #{sourceHash},
       translated_text = NULL,
       status = 'PENDING',
       failure_count = CASE WHEN source_hash = #{sourceHash} THEN failure_count ELSE 0 END,
       retry_after = NULL,
       lease_until = SYSTIMESTAMP + NUMTODSINTERVAL(#{leaseSeconds}, 'SECOND'),
       last_error = NULL,
       updated_at = SYSTIMESTAMP
 WHERE source_type = #{sourceType}
   AND source_key = #{sourceKey}
   AND source_field = #{sourceField}
   AND target_language = #{targetLanguage}
   AND (
        source_hash <> #{sourceHash}
        OR status = 'IDLE'
        OR (status = 'SUCCESS' AND translated_text IS NULL)
        OR (status = 'FAILED' AND (retry_after IS NULL OR retry_after <= SYSTIMESTAMP))
        OR (status = 'PENDING' AND (lease_until IS NULL OR lease_until <= SYSTIMESTAMP))
   )

UPDATE content_translation
   SET translated_text = #{translatedText,jdbcType=CLOB},
       status = 'SUCCESS',
       failure_count = 0,
       retry_after = NULL,
       lease_until = NULL,
       last_error = NULL,
       updated_at = SYSTIMESTAMP
 WHERE source_type = #{sourceType}
   AND source_key = #{sourceKey}
   AND source_field = #{sourceField}
   AND target_language = #{targetLanguage}
   AND source_hash = #{sourceHash}
   AND status = 'PENDING'

UPDATE content_translation
   SET translated_text = NULL,
       status = 'FAILED',
       failure_count = failure_count + 1,
       retry_after = #{retryAfter,jdbcType=TIMESTAMP},
       lease_until = NULL,
       last_error = #{lastError,jdbcType=VARCHAR},
       updated_at = SYSTIMESTAMP
 WHERE source_type = #{sourceType}
   AND source_key = #{sourceKey}
   AND source_field = #{sourceField}
   AND target_language = #{targetLanguage}
   AND source_hash = #{sourceHash}
   AND status = 'PENDING'
